"""More townsfolk for Edinburgh and Prague (original writing). Merged into towns_text.DIALOGUE."""
from towns_text import DIALOGUE, d, N

# ------------------------------------------------------------ EDINBURGH (outdoors)
d("edin_cormac",
  ("Cormac", "Hear ye, hear ye! The South Bridge Vaults remain CLOSED by order of the Burgh! Anyone found ringing bells after curfew will be fined, and anyone found ringing them BEFORE curfew will be thanked, quietly."),
  ("Mu", "Why would anyone be thanked for ringing a bell?"),
  ("Cormac", "Because some nights the vaults ring on their own, and nobody's brave enough to answer. I say a bell that answers back is a friend. The Burgh says it's a nuisance."))
d("edin_cormac_again", ("Cormac", "Hear ye! The crier's lungs are sound, but the news is getting worse."))
d("edin_jean",
  ("Jean", "Washing doesn't dry in this town, it just sulks. And these sheets! Every one's come back from the line with a blue thread sewn through the hem. I never sewed it."),
  ("Isolde", "Blue thread. Mam's spool...?"),
  ("Jean", "Aye, I thought it might be hers. Take one if you like. Somebody out there is mending us."))
d("edin_jean_again", ("Jean", "Another blue thread this morning. Whoever it is, they sew a lovely straight stitch."))
d("edin_ailsa",
  ("Ailsa", "A song for the travellers? 'Seven Bells Below the Bridge'. It's new, and I swear I didn't write it. I woke up humming it. The words are all about a ringer who walked down and never came up."),
  ("Mu", "Does the song say whether he came back?"),
  ("Ailsa", "The last verse always changes. Last night it said: 'he's waiting for someone who remembers.'"))
d("edin_ailsa_again", ("Ailsa", "Tonight the last verse said your name, young man. Don't look at me like that. I only sing them."))
d("edin_dougal",
  ("Dougal", "Watch Recruit Dougal, reporting, sir! Madam! Whoever you are. Captain Hamish says I'm to stand here and look intimidating. Is it working?"),
  ("Isolde", "You're doing wonderfully, Dougal."),
  ("Dougal", "Truly? Only I've been standing here four hours and a goose has been staring me down the entire time."))
d("edin_dougal_again", ("Dougal", "The goose has gone. I like to think I won."))
d("edin_maisie",
  ("Maisie", "Herring! Fresh from the Forth. Well. Fresh from yesterday. The boats came back with no fish and a tangle of old bell-rope in the nets. Same rope as the ones they hung in the vaults, so they say."),
  ("Mu", "Rope from the vaults? In the harbour?"),
  ("Maisie", "Something is draining the vaults into the sea, pet. Or the sea is draining into them. Either way I'm selling herring."))
d("edin_maisie_again", ("Maisie", "Herring! The smell's free, mind."))
d("edin_magnus",
  ("Old Magnus", "Fought at Dunbar, I did. Lost an eye and half a knee and gained a very good story. The story's been getting better with age. The knee's been getting worse."),
  ("Mu", "Did you ever go into the vaults?"),
  ("Old Magnus", "Once, as a lad. The bells down there ring in the wrong order. Seven of them. If you ever hear them rung right... well. Run. Or stay, if you're the sort who can finish what the ringer started."))
d("edin_magnus_again", ("Old Magnus", "Seven bells. Remember that. Seven."))
d("edin_ina",
  ("Ina", "I sell herbs! Mostly weeds, but they smell nice. This one's feverfew. This one's mugwort. This one's... I don't know what this one is. It was growing out of a gravestone and humming."))
d("edin_ina_again", ("Ina", "The humming one grew another leaf. I've named it Gerald."))
d("edin_fraser",
  ("Fraser", "Ratcatcher. Fourteen shillings a hundred. Strange thing, though: the rats have all left the Cowgate. Marching out in a line, they were, all heading the same way. Toward the vaults."),
  ("Isolde", "Rats leaving a place, that's never a good sign."),
  ("Fraser", "Aye. Rats are the best judges of a bad idea. If they're going in, something down there is calling."))
d("edin_fraser_again", ("Fraser", "Tell the rats I said hello. They never listen."))
d("edin_beatrix",
  ("Beatrix", "Forty years I've laid a posy on that unmarked stone. I don't know whose it is. I only know the ground was cold the first day I came, and it seemed unkind to leave it that way."),
  ("Isolde", "That's the kindest reason I've heard in a long time."))
d("edin_beatrix_again", ("Beatrix", "Violets this year. They were the only ones that didn't wilt."))
d("edin_anselm",
  ("Brother Anselm", "Peace, children. I tend the kirk bell on the hill. It has not rung once since the collapse, yet I wake every night to its sound. Perhaps I am being called to listen rather than to ring."),
  ("Mu", "Called by whom?"),
  ("Brother Anselm", "That, I cannot say. But the sound has begun to carry a word. A name. I will not say whose, lest I be wrong, and lest I be right."))
d("edin_anselm_again", ("Brother Anselm", "Go gently. The dark is not an enemy. It is simply unattended."))

# ------------------------------------------------------------ EDINBURGH (indoors)
d("edin_in_candle", ("Ross", "I came in for one pint and I'm on my fourth story. They keep telling me the same one: a ringer, a bridge, a bell. I keep telling them it's not a story. It's my grandfather."))
d("edin_in_archive", ("Clerk Pringle", "Silence, please. The Archive has been scolding me for thirty years. Today it's a draught from the east wall. Someone has been opening a door that isn't there."))
d("edin_in_mason", ("Apprentice Callum", "Duncan says a mason must love stone. I do. I just wish it loved me back. This arch has fallen on me twice. I think it's personal."))
d("edin_in_chandlery", ("Mistress Fenella", "Candles for the dead, candles for the living, and candles for the in-between. That last one's the biggest seller this winter."))
d("edin_in_cottage", ("Old Tibby", "I keep Marta company on the long nights. She knits, I snore. Between us we've mended half of Edinburgh. Not the half we wanted."))
d("edin_in_apoth", ("Patient Gavin", "I've been waiting an hour for a cough remedy. Ewan keeps tasting his own cough remedy and forgetting what's in it."))
d("edin_in_armoury", ("Squire Alec", "I'm to carry my lord's helm and say nothing. I've now said nothing for six days. Please speak to me. About anything."))
d("edin_in_forge", ("Bellows-boy Tom", "Iain says I'll be a smith one day if I stop burning my own eyebrows. I've been practising. They've come back thicker."))
d("edin_in_inn", ("Traveller Esme", "I've slept in forty inns across the Isles, and this is the only one that tucks the blankets in before you've even sat down. I'm staying a week."))

# ------------------------------------------------------------ PRAGUE (outdoors)
d("pra_karel",
  ("Karel", "Night watchman. Which is a lie, because I haven't seen the night in three weeks. The clock stops between chimes and it's always an hour I don't recognise. Today it's half past the thirteenth."),
  ("Isolde", "Half past the thirteenth? You're making that up."),
  ("Karel", "I wish. Ask the clock. It's been counting in the wrong direction since the Hour of Ravens."))
d("pra_karel_again", ("Karel", "Still thirteen. Still half past. I'm getting used to it. That's the worst part."))
d("pra_dorota",
  ("Dorota", "Flowers! Roses, lilies, forget-me-nots! Take a forget-me-not, traveller. They grow wild near the ossuary now. Faster than anyone can pick them. As if the dead are trying to say something."),
  ("Mu", "What do they want to say?"),
  ("Dorota", "'Remember us.' That's what the flowers say. I sell them anyway. Remembering is good business."))
d("pra_dorota_again", ("Dorota", "Forget-me-nots, a penny. The best bargain in Prague."))
d("pra_matyas",
  ("Matyas", "Behold! The Tale of the Brave Locksmith and the Seven Dancing Skeletons! Do you like skeletons? Everyone likes skeletons. They're the only honest actors, they've nothing left to hide."),
  ("Isolde", "Do the puppets ever move on their own?"),
  ("Matyas", "Only since the ossuary opened. I've started leaving a chair out for them. It's only polite."))
d("pra_matyas_again", ("Matyas", "Tonight's show is sold out. The audience is all in the front row. They're very quiet."))
d("pra_rebeka",
  ("Rebeka", "Scribe, translator, and keeper of other people's secrets. I copied a letter last week in a language I've never seen. By morning I understood every word. I wish I hadn't."),
  ("Isolde", "What did it say?"),
  ("Rebeka", "'The hour will be returned when the keeper is.' Whatever that means. I burned it. It didn't help. The words are still in my head."))
d("pra_rebeka_again", ("Rebeka", "I've started writing in my sleep. The ink is always blue."))
d("pra_pavel",
  ("Pavel", "I'm the astronomer's apprentice! Which means I wind the clock, dust the figures, and take the blame. Master Hynek has gone missing, so I've been running the whole thing myself. Badly. Very badly."),
  ("Mu", "Missing? Since when?"),
  ("Pavel", "The night the apostles stopped. He climbed the tower to look at the stars and the stairs just... went on a lot longer than they should."))
d("pra_pavel_again", ("Pavel", "I counted the stairs again. Three hundred and eleven. Yesterday it was two hundred and six."))
d("pra_zora",
  ("Zora", "Fiddle for a coin? I only know three tunes. A waltz, a lament, and one I think I dreamt. People ask for the dreamt one. They cry. I'm not sure whether to be proud."),
  ("Isolde", "Play the dreamt one."),
  ("Zora", "...All right. But hold onto something."))
d("pra_zora_again", ("Zora", "Third verse changed again. It's gotten a lot sadder. Or I have."))
d("pra_bohdan",
  ("Bohdan", "Toll-keeper for the Charles Bridge. The statues keep turning to watch the water. All thirty of them. I put a sack over one's head last night. In the morning the sack was folded on the parapet and he was smiling."))
d("pra_bohdan_again", ("Bohdan", "Pay the toll. Statues don't, but you're not a statue. Probably."))
d("pra_emil",
  ("Emil", "Lamplighter. Every night, the same lamps, in the same order. Lately there's one extra lamp at the end of the lane that I did not put there. It lights itself. It burns a very pale blue."),
  ("Mu", "Blue? Like the thread in Edinburgh?"),
  ("Emil", "I've no idea what that means, but I'll thank you not to be so calm about it."))
d("pra_emil_again", ("Emil", "The blue lamp's burning again. Tell it I said it's not my fault."))
d("pra_vaclav",
  ("Vaclav", "Spare a crumb? I'm not hungry. I just like to be given things. Everyone gets happier when they give. It's a trick I learned. Don't tell anyone."))
d("pra_vaclav_again", ("Vaclav", "You're a good one. I can tell. Your shadow's got a nicer shape than most."))
d("pra_ludmila",
  ("Ludmila", "My husband lies under the third stone. Every evening I tell him what the clock did, and every evening he says nothing. This week I swear I heard the bones laugh. Not cruel. Just... delighted. Like they'd finally heard a good joke."))
d("pra_ludmila_again", ("Ludmila", "I told him you were coming. He seemed pleased."))
d("pra_agnes",
  ("Sister Agnes", "Pilgrim of the Orloj. I walked from Kutna Hora to see the apostles turn. They didn't. I stayed anyway. Sometimes a stopped clock is the most honest face of time, you know. It shows you exactly where you stand."))
d("pra_agnes_again", ("Sister Agnes", "Bless you, travellers. May the hour be kind to you."))

# ------------------------------------------------------------ PRAGUE (indoors)
d("pra_in_tavern", ("Drover Jaroslav", "I came to Prague for the beer and stayed for the ghosts. They're very polite. They never touch the tab."))
d("pra_in_lodge", ("Clockwright Anton", "I've been oiling these gears for twenty years. Last week one turned the wrong way, and the whole lodge exhaled. As if it had been holding its breath."))
d("pra_in_alchemist", ("Student Kasimir", "My master says I'm not allowed to touch the red flask. I've been very good. I've only touched it with a spoon."))
d("pra_in_cartographer", ("Surveyor Beata", "Every map of Prague I draw is slightly bigger than the last. I'm not complaining. I'm just running out of paper."))
d("pra_in_bakery", ("Customer Hana", "The bread here rises even when it's cold. Even when it's stale. I took a loaf home last Tuesday and it's still rising. Please advise."))
d("pra_in_retort", ("Apprentice Tobias", "The tincture smells like pennies and old rain. My master says that's how you know it's working. I think that's how you know it's wrong."))
d("pra_in_guild", ("Squire Ctibor", "The guildmaster told me to stand up straight. I did. Then he told me to stand up straighter. I'm not sure there's any more straight left."))
d("pra_in_steel", ("Journeyman Radek", "Iron remembers every hammer-blow. Master says that's why it's strong. I say that's why it's cranky."))
d("pra_in_rose", ("Guest Lenka", "The Rose and the Hourglass has a clock in every room, and not one agrees with another. I'm sleeping better than I have in years. No idea what time it is."))

# ------------------------------------------------------------ VAULT SECRETS
from towns_text import SECRETS, ITEMS  # noqa: E402

SECRETS.update({
    "v_urn1": "Behind a cracked urn, a tarnished Ringer's Token stamped with seven small bells. Someone left it here for luck.",
    "v_crate": "A rotted crate of altar candles, and under them a Brass Plumb-Bob, still swinging, though there is no draught.",
    "v_barrel": "A cask of ancient small beer. It should be vinegar by now. It tastes of bread and rain, and you feel restored.",
    "v_tomes": "A Ringers' Ledger. Seven names, one struck through, and a margin note in blue ink: 'He went down to tune the sixth. He is still tuning.'",
    "v_chest1": "The chest holds a glass bead the size of a walnut, full of slow red light. It pulses against your palm in time with your bell. Your vitality grows.",
    "v_grave1": "BAELLE WYND, Ringer of the First Bell. 'She taught the dark its key.' The stone is warm.",
    "v_grave2": "TOBIAS KERR, Ringer of the Third Bell. 'He rang until his hands forgot him.' Fresh wax has been dripped at the foot of the slab.",
    "v_grave3": "The slab bears no name, only a small blue thread knotted through the carved bell. It is still tight.",
    "v_urn2": "Inside the urn: a Sexton's Whistle, bone-white, and a scrap of paper that reads only 'Three short. One long.'",
    "v_chest2": "Under a heap of mouldering cloaks, a folded cloak that is not mouldering at all. It slips over your arm like a shadow with good manners.",
    "v_statue": "A stone ringer with her arms raised to a bell that has long since gone. At her feet, an inscription: 'Whoever strikes it last, strikes it for all of us.'",
    "v_crate2": "A crate of Burgh surveyors' chalk, and a rolled Cistern Chart that marks a room you have not found yet. The room is labelled 'Where he is.'",
    "v_chest3": "A reliquary kept for three ringers who never came back together. Inside lies a plain brass bell-pull, and a note: 'Seal the seals in the right hands.' The hands were right. It rings once, in thanks.",
    "v_urn3": "A drowned Ringer's Glove, stiff with lime. The thumb is stitched with blue thread. The stitches are very neat.",
})
ITEMS.update({
    "v_urn1": "Ringer's Token", "v_crate": "Brass Plumb-Bob", "v_tomes": "Ringers' Ledger",
    "v_chest1": "Heart of the Cistern", "v_urn2": "Sexton's Whistle", "v_chest2": "Ringer's Shadecloak",
    "v_crate2": "Cistern Chart", "v_urn3": "Drowned Ringer's Glove", "v_chest3": "Ringers' Reliquary Bell-Pull", "v_barrel": "Old Small Beer",
})
